@use '../theme/variables' as gt;
@use '../theme/animations';

:host {
  display: block;
}

.learn {
  text-align: center;
  padding: 6rem 1.5rem;
  max-width: gt.$max-width;
  margin: 0 auto;
  animation: fadeInUp 0.6s ease-out both;

  &__heading {
    font-size: gt.$hero-font-size;
    font-weight: 800;
    color: var(--gt-primary);
    margin: 0 0 1.5rem;
    line-height: 1.15;
    letter-spacing: -0.02em;
  }

  &__placeholder {
    font-size: gt.$subtitle-font-size;
    color: var(--gt-text-secondary);
    margin: 0 0 3rem;
    line-height: 1.7;
    max-width: 640px;
    margin-left: auto;
    margin-right: auto;
  }

  &__exercises {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: gt.$feature-grid-gap;
    max-width: gt.$max-width;
    margin: 0 auto;
  }

  &__card {
    display: block;
    background: var(--gt-surface);
    border-radius: gt.$border-radius;
    padding: gt.$card-padding;
    box-shadow: var(--gt-card-shadow);
    text-decoration: none;
    text-align: left;
    transition:
      transform gt.$transition-base,
      box-shadow gt.$transition-base;
    animation: fadeInUp 0.6s ease-out both;
    animation-delay: 0.15s;
    cursor: pointer;

    &:hover {
      transform: translateY(-4px);
      box-shadow: var(--gt-card-shadow-hover);
    }

    &:active {
      transform: translateY(-1px);
    }
  }

  &__card-icon {
    font-size: gt.$feature-icon-size;
    margin-bottom: 1rem;
    display: block;
  }

  &__card-title {
    font-size: gt.$feature-title-size;
    font-weight: 700;
    color: var(--gt-text);
    margin: 0 0 0.75rem;
  }

  &__card-description {
    color: var(--gt-text-secondary);
    margin: 0;
    line-height: 1.7;
    font-size: gt.$feature-description-size;
  }
}

@media (max-width: 768px) {
  .learn {
    padding: 4rem 1rem;

    &__heading {
      font-size: gt.$hero-font-size-mobile;
    }

    &__placeholder {
      font-size: 1.1rem;
    }

    &__exercises {
      grid-template-columns: 1fr;
      gap: 1.5rem;
    }
  }
}

import { test, expect } from '@playwright/test';

test.describe('Learn Page', () => {
  test('should display exercises and allow navigation to Fretboard Flash', async ({ page }) => {
    await page.goto('/learn');

    const learnSection = page.getByTestId('learn-section');
    await expect(learnSection).toBeVisible();

    const heading = learnSection.locator('h2');
    await expect(heading).toBeVisible();
    await expect(heading).toContainText(/learn/i);

    // Fretboard Flash card should be visible with title and description
    const fretboardFlashCard = page.getByTestId('exercise-fretboard-flash');
    await expect(fretboardFlashCard).toBeVisible();
    await expect(fretboardFlashCard).toContainText(/fretboard flash/i);

    const description = page.getByTestId('exercise-fretboard-flash-description');
    await expect(description).toBeVisible();

    // Clicking the card navigates to /learn/fretboard-flash
    await fretboardFlashCard.click();
    await expect(page).toHaveURL(/\/learn\/fretboard-flash/);
  });
});

